from datetime import datetime
from datetime import timedelta
from IQCommon.logger import strategy_log
from IQEngine.api.api_base import engine_instance
from IQEngine.core.events import EventEnum
from IQEngine.utils import datetime_func
class TradingDatesMixin(object):
    def __init__(self, dates):
        self._dates = dates
        self.trading_dates_update_flag = True
        self.trading_dates_pre_before_flag = False
        self.engine = engine_instance()
        self.engine.event_bus.append_listener(EventEnum.PRE_BEFORE_TRADING_START, self.on_trading_dates_pre_before)
        self.engine.event_bus.append_listener(EventEnum.AFTER_TRADING_END, self.on_trading_dates_after_trading)
    def get_trading_dates(self, start_date, end_date):
        """
        获取交易日列表
        :param start_date: int/str/datetime 开始日期
        :param end_date: int/str/datetime 结束日期
        :return: list 交易日列表
        """
        self.trading_dates_reload()
        start_date = datetime_func.to_timestamp_dt_date(start_date)
        end_date = datetime_func.to_timestamp_dt_date(end_date)
        left = self._dates.searchsorted(start_date)
        right = self._dates.searchsorted(end_date, side='right')
        return list(self._dates[left:right])
    def get_previous_trading_date(self, date, n=1):
        """
        获取上n个交易日
        :param date: int 日期
        :param n: int 天数
        :return:date 上n个交易日期
        """
        self.trading_dates_reload()
        date = datetime_func.to_timestamp_dt_date(date)
        pos = self._dates.searchsorted(date)
        if pos >= n:
            return self._dates[pos - n]
        else:
            strategy_log.info('所获取交易日超出交易日历范围,返回交易日历的开始日期')
            return self._dates[0]
    def get_next_trading_date(self, date, n=1):
        """
        获取未来n个交易日
        :param date: int / date / datetime日期
        :param n: int 天数
        :return:date 上n个交易日期
        """
        self.trading_dates_reload()
        date = datetime_func.to_timestamp_dt_date(date)
        pos = self._dates.searchsorted(date, side='right')
        if pos + n > len(self._dates):
            strategy_log.info('所获取交易日超出交易日历范围,返回交易日历的结束日期')
            return self._dates[-1]
        else:
            return self._dates[pos + n - 1]
    def is_trading_date(self, date):
        """
        判断是否交易日
        :param date:  int / date / datetime 日期
        :return: bool 是否交易日
        """
        self.trading_dates_reload()
        date = datetime_func.to_timestamp_dt_date(date)
        pos = self._dates.searchsorted(date)
        return pos < len(self._dates) and self._dates[pos] == date
    def _get_future_trading_date(self, dt):
        """
        获取夜盘归属日期
        :param datetime dt:
        :return:
        """
        self.trading_dates_reload()
        date = dt.date()
        if dt.hour > 20:
            date += timedelta(days=1)
        pos = self._dates.searchsorted(date)
        return self._dates[pos]
    def get_trading_dt(self, calendar_dt):
        """
        将实际时间转化为期货交易表时间
        :param calendar_dt: datetime 实际时间
        :return: datetime 交易表时间时间
        """
        self.trading_dates_reload()
        trading_date = self.get_future_trading_date(calendar_dt)
        return datetime.combine(trading_date.date(), calendar_dt.time())
    def get_future_trading_date(self, dt):
        """
        获取期货实际时间归属日期
        :param dt: datetime 实际时间
        :return: date 归属日期
        """
        self.trading_dates_reload()
        dt = datetime_func.to_timestamp(dt)
        return self._get_future_trading_date(dt)
    get_nth_previous_trading_date = get_previous_trading_date
    def get_n_trading_dates_until(self, dt, n):
        """
        获取某日期前n个交易日的数组
        :param dt: date 日期
        :param n: 前数天数
        :return: numpy.ndarray 交易日的数组
        """
        self.trading_dates_reload()
        date = datetime_func.to_timestamp_dt_date(dt)
        pos = self._dates.searchsorted(date, side='right')
        if pos >= n:
            return self._dates[pos - n:pos]
        else:
            return self._dates[:pos]
    def trading_dates_reload(self):
        if not (self.trading_dates_pre_before_flag and self.trading_dates_update_flag):
            self._dates = self.engine.data_engine.get_trading_calendar()
            self.trading_dates_update_flag = True
            return None
    def on_trading_dates_pre_before(self, event):
        self.trading_dates_pre_before_flag = True
    def on_trading_dates_after_trading(self, event):
        self.trading_dates_update_flag = False
        self.trading_dates_pre_before_flag = False
